def match_block(loc, tokens):
    """Process match blocks."""
    match_token = tokens[1]
    if match_token != '(':
        raise SyntaxError("Unexpected token: {}".format(match_token))
    match_expr = tokens[2]
    if match_expr != '=>':
        raise SyntaxError("Unexpected token: {}".format(match_expr))
    match_block = tokens[3]
    if match_block != '{':
        raise SyntaxError("Unexpected token: {}".format(match_block))
    match_block = tokens[4:]
    if match_block[-1] != '}':
        raise SyntaxError("Unexpected token: {}".format(match_block[-1]))
    match_block = match_block[:-1]
    return match_block


